def match(pattern: str, text: str) -> bool:
    """
    Implements regex matching supporting literal characters, '.' (any char),
    '*' (zero or more of the preceding element), and '+' (one or more of the preceding).
    Utilizes a recursive backtracking algorithm to explore all possible matches.
    """
    def is_match(p: str, t: str) -> bool:
        if not p:
            return not t

        first_match = bool(t) and p[0] in {t[0], '.'}

        if len(p) >= 2 and p[1] in {'*', '+'}:
            if p[1] == '*':
                return (is_match(p[2:], t) or
                        first_match and is_match(p, t[1:]))
            elif p[1] == '+':
                return first_match and (is_match(p, t[1:]) or 
                                        is_match(p[2:], t[1:]))

        return first_match and is_match(p[1:], t[1:])

    return is_match(pattern, text)

