    """
    Implements a recursive backtracking algorithm for basic regex matching
    with support for literal characters, '.', '*', and '+'.
    """

    def is_match(p_index: int, t_index: int) -> bool:
        if p_index == len(pattern) and t_index == len(text):
            return True
        if p_index < len(pattern) and t_index < len(text) and \
                (pattern[p_index] == text[t_index] or pattern[p_index] == '.'):
            return is_match(p_index + 1, t_index + 1)

        if p_index < len(pattern):
            if pattern[p_index] == '*':
                return (is_match(p_index - 1, t_index) or 
                        (t_index < len(text) and 
                         (pattern[p_index - 1] == text[t_index] or 
                          pattern[p_index - 1] == '.') and 
                         is_match(p_index, t_index + 1)))
            )
            if pattern[p_index] == '+':
                return (t_index < len(text) and 
                        (pattern[p_index - 1] == text[t_index] or 
                         pattern[p_index - 1] == '.') and 
                        is_match(p_index, t_index + 1))

        if p_index < len(pattern) - 1 and pattern[p_index + 1] == '*':
            return is_match(p_index + 2, t_index)

        return False

    return is_match(0, 0)

