                    match_one_or_more = (t_idx < len(text) and 
                                         is_match(p_idx, t_idx + 1, memo))  # Match at least one
                    result = match_zero or match_one_or_more
                else:  # pattern[p_idx + 1] == '+'
                    result = (t_idx < len(text) and 
                              is_match(p_idx, t_idx + 1, memo))  # Match at least one

            else:
