            result = p_idx + 1 < len(pattern) and pattern[p_idx + 1] == '*' and is_match(p_idx + 2, t_idx, memo)

        else:
            result = False

        memo[(p_idx, t_idx)] = result
        return result

    return is_match(0, 0, {})

