def match(pattern: str, text: str) -> bool:
    """
    Implements a regex matching algorithm with support for literal characters,
    '.', '*', and '+' using a recursive approach with memoization to optimize 
    repeated subproblems.
    """
    from functools import lru_cache

    @lru_cache(None)
    def dp(p_index: int, t_index: int) -> bool:
        if p_index == len(pattern):
            return t_index == len(text)

        first_match = (t_index < len(text)) and (pattern[p_index] in {text[t_index], '.'})

        if p_index + 1 < len(pattern) and pattern[p_index + 1] in {'*', '+'}:
            if pattern[p_index + 1] == '*':
                return (dp(p_index + 2, t_index) or 
                        (first_match and dp(p_index, t_index + 1)))  # zero or more
            elif pattern[p_index + 1] == '+':
                return first_match and (dp(p_index, t_index + 1) or 
                                        dp(p_index + 2, t_index))

        return first_match and dp(p_index + 1, t_index + 1)  # proceed with both

    return dp(0, 0)
